"""Minimal BMP v3 (RFC 7854, 8671, 9069) and BGP-4 (RFC 4271) codec. Standard library only."""
import ipaddress, struct

# ---------- BGP-4 messages (just enough for BMP) ----------
MARKER = b"\xff" * 16
OPEN, UPDATE, NOTIFICATION = 1, 2, 3

def bgp(msg_type, body):
    return MARKER + struct.pack("!HB", 19 + len(body), msg_type) + body

def bgp_open(asn, hold, router_id, afi_safis=((1, 1),)):
    caps = b""
    for afi, safi in afi_safis:                      # capability 1: multiprotocol (RFC 4760)
        caps += struct.pack("!BBHBB", 1, 4, afi, 0, safi)
    caps += struct.pack("!BBI", 65, 4, asn)          # capability 65: 4-octet AS (RFC 6793)
    params = struct.pack("!BB", 2, len(caps)) + caps # optional parameter 2: capabilities
    my_as = asn if asn &lt; 65536 else 23456            # AS_TRANS for 4-byte ASNs
    body = struct.pack("!BHH4sB", 4, my_as, hold, ipaddress.IPv4Address(router_id).packed, len(params))
    return bgp(OPEN, body + params)

def _prefixes(pfxs):
    out = b""
    for p in pfxs:
        n = ipaddress.IPv4Network(p)
        out += bytes([n.prefixlen]) + n.network_address.packed[: (n.prefixlen + 7) // 8]
    return out

def bgp_update(nlri=(), withdrawn=(), as_path=(), next_hop=None, med=None, local_pref=None, communities=()):
    attrs = b""
    if nlri:
        attrs += struct.pack("!BBBB", 0x40, 1, 1, 0)                        # ORIGIN IGP
        seg = struct.pack("!BB", 2, len(as_path)) + b"".join(struct.pack("!I", a) for a in as_path)
        attrs += struct.pack("!BBB", 0x40, 2, len(seg)) + seg               # AS_PATH, 4-byte ASNs
        attrs += struct.pack("!BBB4s", 0x40, 3, 4, ipaddress.IPv4Address(next_hop).packed)
        if med is not None:
            attrs += struct.pack("!BBBI", 0x80, 4, 4, med)
        if local_pref is not None:
            attrs += struct.pack("!BBBI", 0x40, 5, 4, local_pref)
        if communities:
            val = b"".join(struct.pack("!HH", *map(int, c.split(":"))) for c in communities)
            attrs += struct.pack("!BBB", 0xC0, 8, len(val)) + val
    w = _prefixes(withdrawn)
    return bgp(UPDATE, struct.pack("!H", len(w)) + w + struct.pack("!H", len(attrs)) + attrs + _prefixes(nlri))

def bgp_notification(code, subcode, data=b""):
    return bgp(NOTIFICATION, bytes([code, subcode]) + data)

def admin_shutdown(text):
    """Cease / Administrative Shutdown with a shutdown communication (RFC 9003)."""
    raw = text.encode()
    return bgp_notification(6, 2, bytes([len(raw)]) + raw)

def parse_bgp(pdu):
    length, mtype = struct.unpack("!HB", pdu[16:19])
    body = pdu[19:length]
    if mtype == OPEN:
        ver, my_as, hold, rid, plen = struct.unpack("!BHH4sB", body[:10])
        caps, p, asn4 = [], body[10:10 + plen], None
        while p:
            ptype, l = p[0], p[1]
            c = p[2:2 + l]
            while ptype == 2 and c:
                code, cl = c[0], c[1]
                v = c[2:2 + cl]
                if code == 1:
                    afi, _, safi = struct.unpack("!HBB", v)
                    caps.append(f"MP afi={afi} safi={safi}")
                elif code == 65:
                    asn4 = struct.unpack("!I", v)[0]
                    caps.append(f"AS4 {asn4}")
                else:
                    caps.append(f"cap {code}")
                c = c[2 + cl:]
            p = p[2 + l:]
        return {"type": "OPEN", "as": asn4 or my_as, "hold": hold,
                "id": str(ipaddress.IPv4Address(rid)), "caps": caps}
    if mtype == UPDATE:
        wl = struct.unpack("!H", body[:2])[0]
        withdrawn = _parse_prefixes(body[2:2 + wl])
        al = struct.unpack("!H", body[2 + wl:4 + wl])[0]
        attrs = _parse_attrs(body[4 + wl:4 + wl + al])
        nlri = _parse_prefixes(body[4 + wl + al:])
        return {"type": "UPDATE", "withdrawn": withdrawn, "attrs": attrs, "nlri": nlri,
                "eor": not withdrawn and not nlri and not attrs}
    if mtype == NOTIFICATION:
        code, sub = body[0], body[1]
        out = {"type": "NOTIFICATION", "code": code, "subcode": sub}
        if code == 6 and sub in (2, 4) and len(body) &gt; 2:   # RFC 9003 shutdown communication
            n = body[2]
            out["communication"] = body[3:3 + n].decode()
        return out
    return {"type": mtype}

def _parse_prefixes(b):
    out = []
    while b:
        plen = b[0]
        nb = (plen + 7) // 8
        addr = b[1:1 + nb] + b"\x00" * (4 - nb)
        out.append(f"{ipaddress.IPv4Address(addr)}/{plen}")
        b = b[1 + nb:]
    return out

def _parse_attrs(b):
    attrs = {}
    while b:
        flags, code = b[0], b[1]
        if flags & 0x10:
            l, off = struct.unpack("!H", b[2:4])[0], 4
        else:
            l, off = b[2], 3
        v = b[off:off + l]
        if code == 1:
            attrs["origin"] = ["igp", "egp", "incomplete"][v[0]]
        elif code == 2:
            path = []
            while v:
                n = v[1]
                path += [struct.unpack("!I", v[2 + 4 * i:6 + 4 * i])[0] for i in range(n)]
                v = v[2 + 4 * n:]
            attrs["as_path"] = path
        elif code == 3:
            attrs["next_hop"] = str(ipaddress.IPv4Address(v))
        elif code == 4:
            attrs["med"] = struct.unpack("!I", v)[0]
        elif code == 5:
            attrs["local_pref"] = struct.unpack("!I", v)[0]
        elif code == 8:
            attrs["communities"] = [f"{v[i]&lt;&lt;8|v[i+1]}:{v[i+2]&lt;&lt;8|v[i+3]}" for i in range(0, len(v), 4)]
        b = b[off + l:]
    return attrs

# ---------- BMP ----------
ROUTE_MONITORING, STATS, PEER_DOWN, PEER_UP, INITIATION, TERMINATION, ROUTE_MIRRORING = range(7)
TYPE_NAMES = ["RouteMonitoring", "Stats", "PeerDown", "PeerUp", "Initiation", "Termination", "RouteMirroring"]
FLAG_V, FLAG_L, FLAG_A, FLAG_O = 0x80, 0x40, 0x20, 0x10   # RFC 7854 V/L/A, RFC 8671 O
GLOBAL, RD_INSTANCE, LOCAL_INSTANCE, LOC_RIB = 0, 1, 2, 3  # peer types (3 from RFC 9069)
STAT_NAMES = {0: "rejected-by-inbound-policy", 1: "dup-prefix-adverts", 2: "dup-withdraws",
              3: "cluster-list-loop", 4: "as-path-loop", 5: "originator-id-loop", 6: "confed-loop",
              7: "adj-rib-in-routes", 8: "loc-rib-routes", 11: "treat-as-withdraw-updates",
              12: "treat-as-withdraw-prefixes", 13: "dup-updates",
              14: "adj-rib-out-pre-routes", 15: "adj-rib-out-post-routes"}
DOWN_REASONS = {1: "local close, NOTIFICATION follows", 2: "local close, FSM event follows",
                3: "remote close, NOTIFICATION follows", 4: "remote close, no NOTIFICATION",
                5: "peer de-configured from monitoring", 6: "local close, TLV data follows (RFC 9069)"}

def common(mtype, body):
    return struct.pack("!BIB", 3, 6 + len(body), mtype) + body

def per_peer(addr, asn, bgp_id, ts, flags=0, ptype=GLOBAL, pd=0):
    a = ipaddress.ip_address(addr)
    if a.version == 6:
        flags |= FLAG_V
        packed = a.packed
    else:
        packed = b"\x00" * 12 + a.packed       # IPv4 goes in the LAST 4 bytes
    sec, usec = int(ts), int(round((ts - int(ts)) * 1e6))
    return struct.pack("!BBQ16sI4sII", ptype, flags, pd, packed, asn,
                       ipaddress.IPv4Address(bgp_id).packed, sec, usec)

def info_tlvs(items):
    return b"".join(struct.pack("!HH", t, len(v)) + v for t, v in items)

def initiation(sys_descr, sys_name, strings=()):
    items = [(0, s.encode()) for s in strings] + [(1, sys_descr.encode()), (2, sys_name.encode())]
    return common(INITIATION, info_tlvs(items))

def peer_up(peer, local_addr, local_port, remote_port, sent_open, recv_open):
    la = ipaddress.ip_address(local_addr)
    lp = la.packed if la.version == 6 else b"\x00" * 12 + la.packed
    return common(PEER_UP, peer + lp + struct.pack("!HH", local_port, remote_port) + sent_open + recv_open)

def route_monitoring(peer, update):
    return common(ROUTE_MONITORING, peer + update)

def stats_report(peer, counters):
    body = struct.pack("!I", len(counters))
    for stype, value in counters:
        if stype in (7, 8, 14, 15):
            body += struct.pack("!HHQ", stype, 8, value)   # 64-bit gauge
        else:
            body += struct.pack("!HHI", stype, 4, value)   # 32-bit counter
    return common(STATS, peer + body)

def peer_down(peer, reason, data=b""):
    return common(PEER_DOWN, peer + bytes([reason]) + data)

def termination(reason, text=None):
    items = ([(0, text.encode())] if text else []) + [(1, struct.pack("!H", reason))]
    return common(TERMINATION, info_tlvs(items))

def parse_per_peer(b):
    ptype, flags, pd, addr, asn, bid, sec, usec = struct.unpack("!BBQ16sI4sII", b[:42])
    ip = ipaddress.IPv6Address(addr) if flags & FLAG_V else ipaddress.IPv4Address(addr[12:])
    return {"peer_type": ptype, "flags": flags, "pd": pd, "addr": str(ip), "as": asn,
            "bgp_id": str(ipaddress.IPv4Address(bid)), "ts": sec + usec / 1e6,
            "post_policy": bool(flags & FLAG_L), "adj_rib_out": bool(flags & FLAG_O)}

def _take_pdu(b):
    l = struct.unpack("!H", b[16:18])[0]
    return b[:l], b[l:]

def parse_bmp(msg):
    ver, length, mtype = struct.unpack("!BIB", msg[:6])
    if ver != 3:
        raise ValueError(f"BMP version {ver}")
    body = msg[6:length]
    out = {"type": TYPE_NAMES[mtype] if mtype &lt; len(TYPE_NAMES) else mtype}
    if mtype in (INITIATION, TERMINATION):
        tl = []
        while body:
            t, l = struct.unpack("!HH", body[:4])
            tl.append((t, body[4:4 + l]))
            body = body[4 + l:]
        out["tlvs"] = tl
        return out
    out["peer"] = parse_per_peer(body)
    rest = body[42:]
    if mtype == ROUTE_MONITORING:
        out["bgp"] = parse_bgp(rest)
    elif mtype == PEER_UP:
        v6 = out["peer"]["flags"] & FLAG_V
        la = ipaddress.IPv6Address(rest[:16]) if v6 else ipaddress.IPv4Address(rest[12:16])
        lport, rport = struct.unpack("!HH", rest[16:20])
        sent, p = _take_pdu(rest[20:])
        recv, info = _take_pdu(p)
        out.update(local=f"[{la}]:{lport}" if v6 else f"{la}:{lport}", remote_port=rport,
                   sent_open=parse_bgp(sent), recv_open=parse_bgp(recv), info=info)
    elif mtype == STATS:
        n = struct.unpack("!I", rest[:4])[0]
        p, stats = rest[4:], {}
        for _ in range(n):
            t, l = struct.unpack("!HH", p[:4])
            v = p[4:4 + l]
            stats[STAT_NAMES.get(t, f"stat-{t}")] = int.from_bytes(v, "big")
            p = p[4 + l:]
        out["stats"] = stats
    elif mtype == PEER_DOWN:
        reason = rest[0]
        out["reason"] = reason
        out["reason_text"] = DOWN_REASONS.get(reason, "unknown")
        if reason in (1, 3):
            out["notification"] = parse_bgp(rest[1:])
        elif reason == 2:
            out["fsm_event"] = struct.unpack("!H", rest[1:3])[0]
    return out

class Framer:
    """BMP is a byte stream over TCP. Reassemble whole messages from arbitrary chunks."""
    def __init__(self):
        self.buf = b""
    def feed(self, chunk):
        self.buf += chunk
        msgs = []
        while len(self.buf) &gt;= 6:
            length = struct.unpack("!I", self.buf[1:5])[0]
            if len(self.buf) &lt; length:
                break
            msgs.append(self.buf[:length])
            self.buf = self.buf[length:]
        return msgs



