PEERS = {
    "isp-a": dict(addr="192.0.2.1", asn=64501, rid="192.0.2.1", local="192.0.2.2", lport=179, rport=50412),
    "isp-b": dict(addr="2001:db8:b::1", asn=4200000002, rid="198.51.100.1", local="2001:db8:b::2",
                  lport=41820, rport=179),
}
# What each peer sends us (pre-policy), as (prefix, as_path, extra attributes)
RECEIVED = {
    "isp-a": [("203.0.113.0/24", [64501, 64510], {}),
              ("198.18.0.0/15", [64501], {}),                    # benchmarking range: bogon
              ("100.64.0.0/10", [64501, 64666], {}),             # shared address space: bogon
              ("203.0.113.128/25", [64501, 64510], {}),          # longer than /24: filtered
              ("192.0.2.0/24", [64501], {"communities": ["64501:100"]})],
    "isp-b": [("203.0.113.0/24", [4200000002, 64520, 64510], {}),
              ("198.51.100.0/24", [4200000002], {"med": 50})],
}
BOGONS = ("198.18.0.0/15", "100.64.0.0/10", "10.0.0.0/8", "192.168.0.0/16")

def inbound_policy(peer, prefix, as_path, attrs):
    """Return post-policy attributes, or None if rejected."""
    import ipaddress
    net = ipaddress.ip_network(prefix)
    if any(net.subnet_of(ipaddress.ip_network(b)) for b in BOGONS) or net.prefixlen &gt; 24:
        return None
    out = dict(attrs)
    out["local_pref"] = 200 if peer == "isp-a" else 100     # prefer ISP A
    out.pop("communities", None)                              # scrub their communities
    return out

def hdr(name, ts, post=False):
    p = PEERS[name]
    return bmp.per_peer(p["addr"], p["asn"], p["rid"], ts, flags=bmp.FLAG_L if post else 0)

def opens(name):
    p = PEERS[name]
    sent = bmp.bgp_open(R1["asn"], 90, R1["rid"])
    recv = bmp.bgp_open(p["asn"], 180 if name == "isp-a" else 30, p["rid"])
    return sent, recv

def update_for(name, prefix, path, attrs):
    nh = "192.0.2.1" if name == "isp-a" else "198.51.100.1"   # IPv4 NLRI; v6 next hop would need MP_REACH
    return bmp.bgp_update(nlri=[prefix], as_path=path, next_hop=nh, **attrs)

def session(monitor=("pre", "post")):
    msgs = [bmp.initiation("FRRouting 10.5.1 (lab sim)", "r1.lab", ["edge router, rack 3"])]
    ts = T0
    for name in PEERS:
        p = PEERS[name]
        sent, recv = opens(name)
        msgs.append(bmp.peer_up(hdr(name, ts), p["local"], p["lport"], p["rport"], sent, recv))
    rejected = {n: 0 for n in PEERS}
    for name, routes in RECEIVED.items():
        for prefix, path, attrs in routes:
            ts += 0.25
            if "pre" in monitor:
                msgs.append(bmp.route_monitoring(hdr(name, ts), update_for(name, prefix, path, attrs)))
            post = inbound_policy(name, prefix, path, attrs)
            if post is None:
                rejected[name] += 1
            elif "post" in monitor:
                msgs.append(bmp.route_monitoring(hdr(name, ts, post=True), update_for(name, prefix, path, post)))
        for post in (False, True):                                   # End-of-RIB = empty UPDATE
            if ("post" if post else "pre") in monitor:
                msgs.append(bmp.route_monitoring(hdr(name, ts, post), bmp.bgp_update()))
    # incremental changes after the initial dump
    ts += 30
    wd = bmp.bgp_update(withdrawn=["192.0.2.0/24"])
    path = [64501, 64501, 64501, 64510]                               # ISP A starts prepending
    for post in (False, True):
        if ("post" if post else "pre") in monitor:
            msgs.append(bmp.route_monitoring(hdr("isp-a", ts, post), wd))
    ts += 1
    for post in (False, True):
        if ("post" if post else "pre") in monitor:
            msgs.append(bmp.route_monitoring(hdr("isp-a", ts, post), update_for(
                "isp-a", "203.0.113.0/24", path, {"local_pref": 200} if post else {})))
    ts += 10
    for name in PEERS:
        pre = len(RECEIVED[name]) - (1 if name == "isp-a" else 0)
        msgs.append(bmp.stats_report(hdr(name, ts), [(0, rejected[name]), (7, pre)]))
    ts += 60
    msgs.append(bmp.peer_down(hdr("isp-b", ts), 3,
                bmp.admin_shutdown("maintenance CHG-4711, back 02:00 UTC")))
    ts += 5
    msgs.append(bmp.peer_down(hdr("isp-a", ts), 4))                  # TCP reset, no NOTIFICATION
    msgs.append(bmp.termination(0, "bmp targets reconfigured"))
    return msgs



station.py

"""A small BMP monitoring station: frames the TCP stream, keeps pre/post Adj-RIB-In per peer."""
import asyncio, datetime, bmp

class Station:
    def __init__(self, quiet=False):
        self.rib = {}          # (peer addr, "pre"|"post") -&gt; {prefix: attrs}
        self.peers = {}
        self.log = []
        self.quiet = quiet

    def say(self, line):
        self.log.append(line)
        if not self.quiet:
            print(line)

    def handle(self, raw):
        m = bmp.parse_bmp(raw)
        t = m["type"]
        if t == "Initiation":
            kv = {0: "string", 1: "sysDescr", 2: "sysName"}
            self.say("INIT   " + ", ".join(f"{kv[k]}={v.decode()!r}" for k, v in m["tlvs"]))
            return
        if t == "Termination":
            reason = [int.from_bytes(v, "big") for k, v in m["tlvs"] if k == 1][0]
            self.say(f"TERM   reason={reason} " + " ".join(v.decode() for k, v in m["tlvs"] if k == 0))
            return
        p = m["peer"]
        when = datetime.datetime.fromtimestamp(p["ts"], datetime.UTC).strftime("%H:%M:%S.%f")[:-3]
        who = f"{p['addr']} AS{p['as']}"
        if t == "PeerUp":
            s, r = m["sent_open"], m["recv_open"]
            hold = min(s["hold"], r["hold"])
            self.peers[p["addr"]] = who
            self.say(f"UP     {when} {who} local={m['local']} rport={m['remote_port']} "
                     f"hold={hold}s (we {s['hold']}, they {r['hold']}) caps={r['caps']}")
        elif t == "RouteMonitoring":
            kind = "post" if p["post_policy"] else "pre"
            rib = self.rib.setdefault((p["addr"], kind), {})
            u = m["bgp"]
            if u["eor"]:
                self.say(f"EOR    {when} {who} {kind}-policy: {len(rib)} routes")
                return
            for w in u["withdrawn"]:
                rib.pop(w, None)
                self.say(f"WDRAW  {when} {who} {kind:4} {w}")
            for n in u["nlri"]:
                change = "UPDATE" if n in rib else "ADD   "
                rib[n] = u["attrs"]
                a = u["attrs"]
                extra = " ".join(f"{k}={a[k]}" for k in ("local_pref", "med", "communities") if k in a)
                self.say(f"{change} {when} {who} {kind:4} {n:18} path={a['as_path']} {extra}".rstrip())
        elif t == "Stats":
            self.say(f"STATS  {when} {who} {m['stats']}")
        elif t == "PeerDown":
            gone = sum(len(self.rib.pop((p['addr'], k), {})) for k in ("pre", "post"))
            detail = ""
            if "notification" in m:
                n = m["notification"]
                detail = f" NOTIFICATION {n['code']}/{n['subcode']}"
                if "communication" in n:
                    detail += f" {n['communication']!r}"
            self.say(f"DOWN   {when} {who} reason={m['reason']} ({m['reason_text']}){detail}; "
                     f"implicitly withdrew {gone} pre+post entries")

    def policy_diff(self):
        out = []
        for (addr, kind), rib in sorted(self.rib.items()):
            if kind == "pre":
                post = self.rib.get((addr, "post"), {})
                out.append((addr, sorted(set(rib) - set(post))))
        return out

async def serve(station, host, port, done):
    async def on_conn(reader, writer):
        framer = bmp.Framer()
        chunks = 0
        while data := await reader.read(65536):
            chunks += 1
            for msg in framer.feed(data):
                station.handle(msg)
        station.say(f"(connection closed after {chunks} reads, {len(framer.buf)} bytes left over)")
        writer.close()
        done.set()
    return await asyncio.start_server(on_conn, host, port)



