"""Run the BMP lab: a simulated router streams to a real TCP station on 127.0.0.1."""
import asyncio, random, sys, bmp, routersim
from station import Station, serve

def section(title):
    print(f"\n=== {title} ===")

async def router_connect(port, msgs, chunk_max, seed=7):
    """Active router side: connect, write the BMP stream in random-sized TCP writes."""
    _, w = await asyncio.open_connection("127.0.0.1", port)
    stream = b"".join(msgs)
    rnd, i = random.Random(seed), 0
    while i &lt; len(stream):
        n = rnd.randint(1, chunk_max)
        w.write(stream[i:i + n])
        await w.drain()
        await asyncio.sleep(0)            # let the station read between writes
        i += n
    w.close()
    await w.wait_closed()
    return len(stream)

async def run_station(msgs, chunk_max, quiet=False):
    st, done = Station(quiet=quiet), asyncio.Event()
    srv = await serve(st, "127.0.0.1", 0, done)
    port = srv.sockets[0].getsockname()[1]
    nbytes = await router_connect(port, msgs, chunk_max)
    await done.wait()
    srv.close()
    return st, nbytes

async def naive(msgs, chunk_max):
    """Wrong: assumes one read() == one BMP message."""
    ok = bad = 0      # ok counts messages decoded; anything after the first in a read is lost
    done = asyncio.Event()
    async def on_conn(r, w):
        nonlocal ok, bad
        while data := await r.read(65536):
            try:
                bmp.parse_bmp(data)
                ok += 1
            except Exception:
                bad += 1
        done.set()
    srv = await asyncio.start_server(on_conn, "127.0.0.1", 0)
    await router_connect(srv.sockets[0].getsockname()[1], msgs, chunk_max)
    await done.wait()
    srv.close()
    return ok, bad

async def main():
    msgs = routersim.session()
    section("1. One BMP session, written in random 1-40 byte TCP chunks")
    st, nbytes = await run_station(msgs, 40)
    print(f"{len(msgs)} BMP messages, {nbytes} bytes")

    section("2. What did inbound policy drop? (pre-policy minus post-policy, before Peer Down)")
    st2, _ = await run_station(msgs[:-3], 1500, quiet=True)   # stop before the two Peer Downs
    for addr, dropped in st2.policy_diff():
        print(f"{addr:16} dropped by policy: {dropped if dropped else 'nothing'}")

    section("3. Per-peer header bytes (IPv4 sits in the last 4 of 16 address bytes)")
    for name in ("isp-a", "isp-b"):
        h = routersim.hdr(name, routersim.T0)
        print(f"{name}: type={h[0]} flags=0x{h[1]:02x} PD={h[2:10].hex()}")
        print(f"       addr={h[10:26].hex()} AS={int.from_bytes(h[26:30],'big')} id={h[30:34].hex()}")

    section("4. Same stream, naive station that treats every read() as one message")
    for cmax in (1500, 40):
        ok, bad = await naive(msgs, cmax)
        print(f"writes up to {cmax:4} bytes: decoded {ok:2} of {len(msgs)} messages, "
              f"{bad:3} reads raised errors")

    section("5. Post-policy only: can you still see the bogons?")
    post_only = routersim.session(monitor=("post",))
    st5, _ = await run_station(post_only[:-3], 1500, quiet=True)
    for (addr, kind), rib in sorted(st5.rib.items()):
        print(f"{addr:16} {kind}: {sorted(rib)}")
    print("pre-policy RIBs seen:", [k for k in st5.rib if k[1] == "pre"])

asyncio.run(main())

The tool: snapshot, run, diff
Counters are cumulative since boot (or since namespace creation), so their absolute values mean little. What you want is the delta across an event. netdelta.py takes one or more namespace names and a command, snapshots every counter in those namespaces and the kernel-wide tables, runs the command, snapshots again and prints the counters that moved. By default it prints only counters whose names look like drops, errors or rate limiting; --all prints everything.


netdelta.py

#!/usr/bin/env python3
"""netdelta.py: snapshot the kernel's drop-related counters, run a command, print what moved.

Usage: netdelta.py [--all] [--ns NAME]... -- command args...
Only counters whose names look like drops or errors are printed, unless --all.
Sources: nstat -saz (SNMP + netstat MIBs, per namespace), ip -s -j link (per device),
and three kernel-wide tables: /proc/net/softnet_stat, /proc/net/stat/rt_cache, /proc/net/stat/arp_cache.
"""
import json, re, subprocess, sys

DROPPY = re.compile(r"Drop|Discard|Err|NoRoute|NoPort|Overflow|Fail|Filter|TimeExcd|DestUnreach|Prune|Collapse|dropped|errors|squeeze|InAddr|Csum|RateLimit")

def sh(ns, *argv):
    pre = ["ip", "netns", "exec", ns] if ns else []
    return subprocess.run(pre + list(argv), capture_output=True, text=True).stdout

def snapshot(ns):
    snap = {}
    data = json.loads(sh(ns, "nstat", "-saz", "--json") or "{}")
    for table in data.values():
        for k, v in table.items():
            snap[k] = v
    for dev in json.loads(sh(ns, "ip", "-s", "-j", "link") or "[]"):
        st = dev.get("stats64", {})
        for d in ("rx", "tx"):
            for k in ("dropped", "errors"):
                snap[f"{dev['ifname']}.{d}_{k}"] = st.get(d, {}).get(k, 0)
    return snap

def global_snapshot():
    """Kernel-wide counters: NOT per network namespace, so other traffic on the host shows up too."""
    snap = {}
    for cpu, row in enumerate(open("/proc/net/softnet_stat")):
        f = [int(x, 16) for x in row.split()]
        snap[f"softnet.cpu{cpu}.dropped"] = f[1]
        snap[f"softnet.cpu{cpu}.time_squeeze"] = f[2]
    rows = open("/proc/net/stat/rt_cache").read().split("\n")
    names = rows[0].split()
    for name in ("in_no_route", "in_martian_dst", "in_martian_src"):
        i = names.index(name)
        snap[f"rt_cache.{name}"] = sum(int(r.split()[i], 16) for r in rows[1:] if r.strip())
    # /proc/net/stat/arp_cache only exists in the initial namespace; ip ntable works everywhere
    out = subprocess.run(["ip", "-s", "ntable", "show", "name", "arp_cache"],
                         capture_output=True, text=True).stdout
    for name in ("res_failed", "unresolved_discards", "table_fulls"):
        m = re.search(rf"\b{name} (\d+)", out)
        if m:
            snap[f"arp_cache.{name}"] = int(m.group(1))
    return snap

def main():
    args = sys.argv[1:]
    nss, show_all = [], False
    if args and args[0] == "--all":
        show_all, args = True, args[1:]
    while args and args[0] == "--ns":
        nss.append(args[1]); args = args[2:]
    if args and args[0] == "--":
        args = args[1:]
    nss = nss or [None]
    before = {ns: snapshot(ns) for ns in nss}
    gbefore = global_snapshot()
    rc = subprocess.run(args).returncode
    gafter = global_snapshot()
    for ns in nss:
        after = snapshot(ns)
        moved = {k: after[k] - before[ns].get(k, 0) for k in after
                 if after[k] != before[ns].get(k, 0) and (show_all or DROPPY.search(k))}
        for k in sorted(moved):
            print(f"   [{ns or 'host'}] {k:&lt;34} +{moved[k]}")
    for k in sorted(gafter):
        if gafter[k] != gbefore[k] and (show_all or DROPPY.search(k) or k.startswith(("rt_cache", "arp_cache"))):
            print(f"   [kernel-wide] {k:&lt;28} +{gafter[k] - gbefore[k]}")
    return rc

if __name__ == "__main__":
    sys.exit(main())

Three implementation details are worth knowing because they reflect real kernel quirks:

/proc/net/stat/arp_cache exists only in the initial network namespace. Inside any other namespace the file is simply missing (the first version of this tool crashed on it). ip -s ntable show name arp_cache returns the same neighbour-table statistics from anywhere, so the tool parses that instead.
/proc/net/stat/rt_cache is visible inside every namespace but its counters are global per-CPU counters, summed here across CPUs.
The DROPPY filter is a heuristic. It deliberately includes RateLimit and DestUnreach because “the router counted the drop but never told the sender” is half of what you are looking for.

NETCONF: transactions over SSH
NETCONF (RFC 6241) is an RPC protocol carried over SSH (RFC 6242) on TCP port 830, as the SSH subsystem netconf. Messages are XML.

Both sides send &lt;hello&gt; with their capabilities: protocol versions (base:1.0, base:1.1), optional features (:candidate, :confirmed-commit, :validate), and the YANG modules supported.
The client sends &lt;rpc&gt; elements with a message-id. The server answers each with &lt;rpc-reply&gt; carrying the same id, containing &lt;ok/&gt;, data, or &lt;rpc-error&gt;.


Datastores







Datastore
Meaning




running
The active configuration


candidate
A scratch copy. Changes here do nothing until &lt;commit&gt;


startup
What loads at boot, on devices that separate it


operational (NMDA, RFC 8342)
Config plus state as actually applied, read with &lt;get-data&gt; (RFC 8526)





Operations







RPC
Purpose




&lt;get-config&gt;
Read configuration from a datastore, optionally filtered


&lt;get&gt;
Read configuration and state (pre-NMDA)


&lt;edit-config&gt;
Change a datastore


&lt;lock&gt; / &lt;unlock&gt;
Stop other sessions changing a datastore while you work


&lt;validate&gt;
Check the candidate without applying


&lt;commit&gt;
Make candidate the running configuration


&lt;commit&gt;&lt;confirmed/&gt;
Commit with automatic rollback unless confirmed (default 600 s)


&lt;discard-changes&gt;
Throw the candidate away



edit-config takes an operation attribute on any element:







Operation
Effect on that subtree




merge (default)
Combine with what exists


replace
Make the subtree exactly this; siblings you did not send are removed


create
Add; error if it already exists


delete
Remove; error if it does not exist


remove
Remove if present; no error if absent



The safe change pattern on a device with :candidate and :confirmed-commit:
lock candidate
edit-config target=candidate (one or many)
validate candidate
commit confirmed confirm-timeout=120
   ... verify reachability from a NEW session ...
commit                 (confirm)   or   let it time out (rollback)
unlock candidate
This is the same idea as the scheduled rollback in the nftables chapter, built into the protocol.


Building an edit-config by hand
ncclient (Python) is the usual client, but it helps to see the bytes once. This program builds an edit-config that sets an OpenConfig interface description in the candidate datastore, then frames it the way NETCONF 1.1 does:


netconf-edit.py

"""Build a NETCONF &lt;edit-config&gt; RPC for an OpenConfig interface description,
and frame it with NETCONF 1.1 chunked framing (RFC 6242)."""
import sys
import xml.etree.ElementTree as ET

NC = "urn:ietf:params:xml:ns:netconf:base:1.0"
OC = "http://openconfig.net/yang/interfaces"
ET.register_namespace("nc", NC)  # an attribute needs a prefix to be in a namespace
ET.register_namespace("oc-if", OC)

def edit_config(ifname, descr, operation, msg_id):
    rpc = ET.Element(f"{{{NC}}}rpc", {"message-id": str(msg_id)})
    ec = ET.SubElement(rpc, f"{{{NC}}}edit-config")
    ET.SubElement(ET.SubElement(ec, f"{{{NC}}}target"), f"{{{NC}}}candidate")
    cfg = ET.SubElement(ec, f"{{{NC}}}config")
    ifs = ET.SubElement(cfg, f"{{{OC}}}interfaces")
    i = ET.SubElement(ifs, f"{{{OC}}}interface")
    ET.SubElement(i, f"{{{OC}}}name").text = ifname
    c = ET.SubElement(i, f"{{{OC}}}config", {f"{{{NC}}}operation": operation})
    ET.SubElement(c, f"{{{OC}}}name").text = ifname
    ET.SubElement(c, f"{{{OC}}}description").text = descr
    ET.indent(rpc)
    return ET.tostring(rpc, encoding="unicode")

body = edit_config(sys.argv[1], sys.argv[2], sys.argv[3], 101)
print(body)
data = body.encode()
print("--- chunked framing (NETCONF 1.1) ---")
print(f"\n#{len(data)}\n{body}\n##")

