rfctables.py:
"""Parse the HPACK Huffman code and static tables, and the QPACK static
table, straight from the RFC text files (rfc7541.txt, rfc9204.txt)."""
import re, pathlib

def _page_clean(text):
    # drop RFC page footers/headers so table rows are contiguous
    return "\n".join(l for l in text.splitlines()
                     if not re.match(r"^(Peon & Ruellan|Krasic, et al\.|RFC 7541 |RFC 9204 )", l))

def huffman():
    t = pathlib.Path("rfc7541.txt").read_text()
    codes = {}
    for m in re.finditer(r"\(\s*(\d+)\)\s+\|([01|]+)\s+([0-9a-f]+)\s+\[\s*(\d+)\]", t):
        sym, bits, hexv, n = int(m[1]), m[2].replace("|", ""), int(m[3], 16), int(m[4])
        assert len(bits) == n and int(bits, 2) == hexv
        codes[sym] = (hexv, n)
    assert len(codes) == 257
    return codes

def hpack_static():
    t = _page_clean(pathlib.Path("rfc7541.txt").read_text())
    a = t.rindex("\nAppendix A.  Static Table Definition"); t = t[a:t.index("\nAppendix B.", a)]
    rows = re.findall(r"^\s+\| (\d+)\s+\| (\S+)\s+\| (.*?)\s*\|$", t, re.M)
    tbl = [(n, v) for _, n, v in rows]
    assert len(tbl) == 61
    return tbl

def qpack_static():
    t = _page_clean(pathlib.Path("rfc9204.txt").read_text())
    a = t.rindex("\nAppendix A.  Static Table"); t = t[a:t.index("\nAppendix B.", a)]
    out = []
    for line in t.splitlines():
        m = re.match(r"^\s+\| (\d*)\s*\| (.*?)\s*\| (.*?)\s*\|$", line)
        if not m:
            continue
        idx, name, val = m.groups()
        if idx == "Index":
            continue
        if idx:
            out.append([name, val])
        else:  # continuation row of a wrapped cell
            out[-1][0] += name; out[-1][1] += (" " if val and out[-1][1].endswith(";") else "") + val
    assert len(out) == 99, len(out)
    return [tuple(x) for x in out]

if __name__ == "__main__":
    h = huffman(); s = hpack_static(); q = qpack_static()
    print(f"Huffman symbols: {len(h)}; shortest {min(n for _, n in h.values())} bits, longest {max(n for _, n in h.values())} bits")
    print(f"HPACK static table: {len(s)} entries; 1={s[0]} 61={s[60]}")
    print(f"QPACK static table: {len(q)} entries; 0={q[0]} 98={q[98]}")
    for i, (n, v) in enumerate(q):
        if len(v) &gt; 40: print(f"  wrapped QPACK entry {i}: {n}: {v}")
hpack.py:
"""Minimal HPACK (RFC 7541) encoder/decoder: integers, Huffman strings,
static + dynamic table with eviction, all four field representations."""
from rfctables import huffman, hpack_static

CODES = huffman()
STATIC = hpack_static()
_DEC = {}
for sym, (code, n) in CODES.items():
    _DEC[(code, n)] = sym

def enc_int(value, prefix_bits, first_byte_flags=0):
    limit = (1 &lt;&lt; prefix_bits) - 1
    if value &lt; limit:
        return bytes([first_byte_flags | value])
    out = [first_byte_flags | limit]; value -= limit
    while value &gt;= 128:
        out.append((value & 0x7f) | 0x80); value &gt;&gt;= 7
    out.append(value)
    return bytes(out)

def dec_int(buf, pos, prefix_bits):
    limit = (1 &lt;&lt; prefix_bits) - 1
    value = buf[pos] & limit; pos += 1
    if value &lt; limit:
        return value, pos
    shift = 0
    while True:
        b = buf[pos]; pos += 1
        value += (b & 0x7f) &lt;&lt; shift; shift += 7
        if not b & 0x80:
            return value, pos

def huff_encode(data):
    acc = nbits = 0; out = bytearray()
    for ch in data:
        code, n = CODES[ch]
        acc = (acc &lt;&lt; n) | code; nbits += n
        while nbits &gt;= 8:
            nbits -= 8; out.append((acc &gt;&gt; nbits) & 0xff)
    if nbits:
        out.append(((acc &lt;&lt; (8 - nbits)) | ((1 &lt;&lt; (8 - nbits)) - 1)) & 0xff)  # pad with EOS prefix (1s)
    return bytes(out)

def huff_decode(data):
    out = bytearray(); code = n = 0
    for byte in data:
        for i in range(7, -1, -1):
            code = (code &lt;&lt; 1) | ((byte &gt;&gt; i) & 1); n += 1
            sym = _DEC.get((code, n))
            if sym is not None:
                if sym == 256:
                    raise ValueError("EOS in string")
                out.append(sym); code = n = 0
    if n &gt; 7 or code != (1 &lt;&lt; n) - 1:
        raise ValueError("bad Huffman padding")
    return bytes(out)

def enc_str(s, huff):
    raw = s.encode()
    if huff:
        h = huff_encode(raw)
        if len(h) &lt;= len(raw):         # use Huffman unless it would be longer
            return enc_int(len(h), 7, 0x80) + h
    return enc_int(len(raw), 7, 0) + raw

def dec_str(buf, pos):
    huff = buf[pos] & 0x80
    n, pos = dec_int(buf, pos, 7)
    data = buf[pos:pos + n]
    return (huff_decode(data) if huff else data).decode(), pos + n

class Table:
    def __init__(self, max_size=4096):
        self.dyn, self.size, self.max = [], 0, max_size
    @staticmethod
    def entry_size(name, value):
        return 32 + len(name.encode()) + len(value.encode())
    def get(self, idx):
        if idx == 0:
            raise ValueError("index 0")
        if idx &lt;= len(STATIC):
            return STATIC[idx - 1]
        return self.dyn[idx - len(STATIC) - 1]
    def add(self, name, value):
        sz = self.entry_size(name, value)
        while self.dyn and self.size + sz &gt; self.max:
            n, v = self.dyn.pop(); self.size -= self.entry_size(n, v)
        if sz &lt;= self.max:
            self.dyn.insert(0, (name, value)); self.size += sz
    def resize(self, new):
        self.max = new
        while self.dyn and self.size &gt; self.max:
            n, v = self.dyn.pop(); self.size -= self.entry_size(n, v)
    def find(self, name, value):
        exact = name_idx = None
        for i, (n, v) in enumerate(STATIC + self.dyn, 1):
            if n == name:
                if v == value and exact is None:
                    exact = i
                if name_idx is None:
                    name_idx = i
        return exact, name_idx

class Encoder:
    """never_index: names sent as 'never indexed' literals (e.g. authorization)."""
    def __init__(self, max_size=4096, huffman=True, never_index=(), no_index=()):
        self.t, self.huff = Table(max_size), huffman
        self.never, self.noidx = set(never_index), set(no_index)
        self.pending_resize = None
    def resize(self, n):
        self.pending_resize = n
    def encode(self, headers):
        out = bytearray()
        if self.pending_resize is not None:
            out += enc_int(self.pending_resize, 5, 0x20); self.t.resize(self.pending_resize); self.pending_resize = None
        for name, value in headers:
            exact, nidx = self.t.find(name, value)
            if name in self.never:
                out += enc_int(nidx or 0, 4, 0x10)
            elif name in self.noidx:
                out += enc_int(nidx or 0, 4, 0x00)
            elif exact:
                out += enc_int(exact, 7, 0x80); continue
            else:
                out += enc_int(nidx or 0, 6, 0x40)
                self.t.add(name, value)
            if not nidx:
                out += enc_str(name, self.huff)
            out += enc_str(value, self.huff)
        return bytes(out)

class Decoder:
    def __init__(self, max_size=4096, max_header_list_size=None):
        self.t, self.limit = Table(max_size), max_header_list_size
    def decode(self, buf):
        pos, headers, list_size = 0, [], 0
        while pos &lt; len(buf):
            b = buf[pos]
            if b & 0x80:
                idx, pos = dec_int(buf, pos, 7); name, value = self.t.get(idx); kind = "indexed"
            elif b & 0xe0 == 0x20:
                n, pos = dec_int(buf, pos, 5); self.t.resize(n); continue
            else:
                prefix, kind = (6, "incremental") if b & 0x40 else ((4, "never") if b & 0x10 else (4, "noindex"))
                idx, pos = dec_int(buf, pos, prefix)
                if idx:
                    name = self.t.get(idx)[0]
                else:
                    name, pos = dec_str(buf, pos)
                value, pos = dec_str(buf, pos)
                if kind == "incremental":
                    self.t.add(name, value)
            list_size += Table.entry_size(name, value)   # RFC 9113 SETTINGS_MAX_HEADER_LIST_SIZE accounting
            if self.limit is not None and list_size &gt; self.limit:
                raise OverflowError(f"header list exceeds {self.limit} bytes after {len(headers)} fields")
            headers.append((name, value, kind))
        return headers, list_size
hpack-vectors.py:
#!/usr/bin/env python3
"""Check hpack.py against every example in RFC 7541 Appendix C."""
import re
from hpack import enc_int, dec_int, Encoder, Decoder
from rfctables import _page_clean

txt = _page_clean(open("rfc7541.txt").read())
txt = txt[txt.rindex("\nAppendix C.  Examples"):]

print("C.1 integers:", enc_int(10, 5).hex(), enc_int(1337, 5).hex(), enc_int(42, 8).hex(),
      "decode 1337 -&gt;", dec_int(enc_int(1337, 5), 0, 5)[0])

def examples(section):
    blocks = re.split(r"\n(C\.\d\.\d)\.  ", txt)
    for i in range(1, len(blocks), 2):
        if blocks[i].startswith(section):
            body = blocks[i + 1]
            hl = body.split("Header list to encode:")[1].split("Hex dump")[0]
            headers = [tuple(l.strip().split(": ", 1)) if ": " in l.strip() else (l.strip().rstrip(":"), "")
                       for l in hl.strip().splitlines() if l.strip()]
            hexpart = body.split("Hex dump of encoded data:")[1].split("Decoding process:")[0]
            hexstr = "".join(re.findall(r"^\s+((?:[0-9a-f]{2,4} ?)+)\s+\|", hexpart, re.M)).replace(" ", "")
            size = int(re.findall(r"Table size:\s+(\d+)", body)[-1])
            yield blocks[i], headers, bytes.fromhex(hexstr), size

