#!/usr/bin/env python3
"""What HPACK's design choices cost and buy on a single HTTP/2 connection."""
import os, base64
from hpack import Encoder, Decoder, huff_encode

def h1_size(headers):  # same fields as HTTP/1.1 text, for scale
    return sum(len(n) + 2 + len(v) + 2 for n, v in headers)

def requests(n):
    for i in range(n):
        yield [(":method", "GET"), (":scheme", "https"), (":authority", "shop.example.net"),
               (":path", f"/api/items/{1000 + i}?page=1"),
               ("user-agent", "Mozilla/5.0 (X11; Linux x86_64; rv:140.0) Gecko/20100101 Firefox/140.0"),
               ("accept", "application/json"), ("accept-language", "en-GB,en;q=0.9"),
               ("accept-encoding", "gzip, deflate, br, zstd"),
               ("cookie", "session=Y2FmZWJhYmUtZmFjZS1jYWZlLWJhYmUtMTIzNDU2Nzg5MA"),
               ("authorization", "Bearer eyJhbGciOiJFUzI1NiJ9.eyJzdWIiOiJrMTlnIn0.c2lnbmF0dXJl")]

print("== 1. Ten requests on one connection (4096-byte dynamic table, Huffman on) ==")
enc = Encoder(4096); total_h1 = total_hp = 0
for i, h in enumerate(requests(10), 1):
    b = enc.encode(h); total_h1 += h1_size(h); total_hp += len(b)
    if i in (1, 2, 3, 10):
        print(f"request {i:2d}: HTTP/1.1 text {h1_size(h)} B -&gt; HPACK {len(b):3d} B   (table {enc.t.size} B, {len(enc.t.dyn)} entries)")
print(f"total: {total_h1} B -&gt; {total_hp} B ({100 * total_hp / total_h1:.1f}%)")

print("\n== 2. SETTINGS_HEADER_TABLE_SIZE changes the steady state ==")
for size in (0, 256, 1024, 4096):
    enc = Encoder(size); sizes = [len(enc.encode(h)) for h in requests(10)]
    print(f"table {size:4d} B: first {sizes[0]:3d} B, later requests {min(sizes[1:])}-{max(sizes[1:])} B, total {sum(sizes)} B")

print("\n== 3. Huffman helps text, not random bytes ==")
samples = {"hostname": "shop.example.net", "path": "/api/items/1000?page=1",
           "user-agent": "Mozilla/5.0 (X11; Linux x86_64; rv:140.0) Gecko/20100101 Firefox/140.0",
           "base64url token (48 random bytes)": base64.urlsafe_b64encode(os.urandom(48)).decode(),
           "hex token (32 random bytes)": os.urandom(32).hex(),
           "printable punctuation": "{}&lt;&gt;[]^~|\\`" * 4}
for label, s in samples.items():
    h = len(huff_encode(s.encode()))
    print(f"{label:34s}: raw {len(s):3d} B, Huffman {h:3d} B ({100 * h / len(s):5.1f}%) -&gt; encoder picks {'Huffman' if h &lt; len(s) else 'raw'}")

print("\n== 4. Guessing a secret through the shared table (CRIME-style, whole values only) ==")
secret = "session=Y2FmZWJhYmUtZmFjZS1jYWZlLWJhYmUtMTIzNDU2Nzg5MA"
guesses = ["session=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA",
           "session=Y2FmZWJhYmUtZmFjZS1jYWZlLWJhYmUtMTIzNDU2Nzg5MB",   # right except last char
           secret]
for policy, kw in [("cookie indexed (default)", {}), ("cookie never-indexed", {"never_index": {"cookie"}})]:
    print(f"-- encoder policy: {policy}")
    enc = Encoder(4096, **kw)
    enc.encode([(":method", "GET"), ("cookie", secret)])               # victim request primes the table
    for g in guesses:
        b = enc.encode([("cookie", g)])                                 # attacker-influenced request
        tag = "correct" if g == secret else ("all but last char" if g[:-1] == secret[:-1] else "wrong")
        print(f"   guess {tag:17s}: {len(b):2d} B on the wire")

print("\n== 5. Decompression amplification and SETTINGS_MAX_HEADER_LIST_SIZE ==")
enc = Encoder(4096)
big = ("x-pad", "A" * 4000)
block = enc.encode([big])   # literal with incremental indexing: lands in the table
refs = enc.encode([big])    # every later use is a 1-byte indexed reference  # now 1-byte indexed reference
payload = block + refs * 16000
print(f"encoded block: {len(payload)} B ({len(block)} B literal insert + 16000 x {len(refs)}-byte references)")
fields, size = Decoder(4096).decode(payload)
print(f"no limit   : {len(fields)} fields, header list size {size} B ({size / len(payload):.0f}x the bytes received)")
try:
    Decoder(4096, max_header_list_size=65536).decode(payload)
except OverflowError as e:
    print(f"limit 64 KiB: rejected: {e}")
