"""Minimal QPACK (RFC 9204): encoder-stream instructions, field sections
with Required Insert Count / Base, decoder-stream acknowledgements."""
from hpack import enc_int, dec_int, huff_encode, huff_decode
from rfctables import qpack_static

STATIC = qpack_static()

def qstr(s, prefix_bits, flags=0, huff=False):
    raw = s.encode()
    h = huff_encode(raw) if huff else None
    if h is not None and len(h) &lt;= len(raw):
        return enc_int(len(h), prefix_bits, flags | (1 &lt;&lt; prefix_bits)) + h
    return enc_int(len(raw), prefix_bits, flags) + raw

def qstr_dec(buf, pos, prefix_bits):
    huff = buf[pos] & (1 &lt;&lt; prefix_bits)
    n, pos = dec_int(buf, pos, prefix_bits)
    data = buf[pos:pos + n]
    return (huff_decode(data) if huff else data).decode(), pos + n

def esize(n, v):
    return 32 + len(n.encode()) + len(v.encode())

class DynTable:
    def __init__(self):
        self.entries, self.capacity, self.inserted, self.dropped = [], 0, 0, 0
    @property
    def size(self):
        return sum(esize(n, v) for n, v in self.entries)
    def insert(self, n, v):
        while self.entries and self.size + esize(n, v) &gt; self.capacity:
            self.entries.pop(0); self.dropped += 1
        self.entries.append((n, v)); self.inserted += 1
    def absolute(self, a):
        return self.entries[a - self.dropped]
    def dump(self):
        return [(self.dropped + i, n, v) for i, (n, v) in enumerate(self.entries)]

class QDecoder:
    def __init__(self, max_capacity):
        self.t, self.max_cap = DynTable(), max_capacity
        self.blocked = {}
    def encoder_stream(self, buf):
        pos, log = 0, []
        while pos &lt; len(buf):
            b = buf[pos]
            if b & 0x80:                                  # Insert With Name Reference
                static = b & 0x40
                idx, pos = dec_int(buf, pos, 6)
                name = STATIC[idx][0] if static else self.t.absolute(self.t.inserted - 1 - idx)[0]
                value, pos = qstr_dec(buf, pos, 7)
                self.t.insert(name, value); log.append(f"Insert With Name Reference ({'static' if static else 'dynamic rel'} {idx}) {name}={value}")
            elif b & 0x40:                                # Insert With Literal Name
                name, pos = qstr_dec(buf, pos, 5)
                value, pos = qstr_dec(buf, pos, 7)
                self.t.insert(name, value); log.append(f"Insert With Literal Name {name}={value}")
            elif b & 0x20:                                # Set Dynamic Table Capacity
                cap, pos = dec_int(buf, pos, 5); self.t.capacity = cap; log.append(f"Set Dynamic Table Capacity={cap}")
            else:                                         # Duplicate
                idx, pos = dec_int(buf, pos, 5)
                n, v = self.t.absolute(self.t.inserted - 1 - idx); self.t.insert(n, v); log.append(f"Duplicate rel {idx} -&gt; {n}={v}")
        return log
    def required_insert_count(self, enc_ric):
        if enc_ric == 0:
            return 0
        max_entries = self.max_cap // 32
        full = 2 * max_entries
        max_value = self.t.inserted + max_entries
        max_wrapped = (max_value // full) * full
        ric = max_wrapped + enc_ric - 1
        if ric &gt; max_value:
            ric -= full
        return ric
    def field_section(self, stream_id, buf):
        """Returns (fields, decoder-stream bytes) or ('BLOCKED', ric)."""
        enc_ric, pos = dec_int(buf, 0, 8)
        ric = self.required_insert_count(enc_ric)
        sign = buf[pos] & 0x80
        delta, pos = dec_int(buf, pos, 7)
        base = ric - delta - 1 if sign else ric + delta
        if ric &gt; self.t.inserted:
            self.blocked[stream_id] = buf
            return "BLOCKED", ric
        out = []
        while pos &lt; len(buf):
            b = buf[pos]
            if b & 0x80:                                   # Indexed Field Line
                static = b & 0x40; idx, pos = dec_int(buf, pos, 6)
                out.append(STATIC[idx] if static else self.t.absolute(base - 1 - idx))
            elif b & 0x40:                                 # Literal With Name Reference
                static = b & 0x10; idx, pos = dec_int(buf, pos, 4)
                name = STATIC[idx][0] if static else self.t.absolute(base - 1 - idx)[0]
                value, pos = qstr_dec(buf, pos, 7); out.append((name, value))
            elif b & 0x20:                                 # Literal With Literal Name
                name, pos = qstr_dec(buf, pos, 3); value, pos = qstr_dec(buf, pos, 7); out.append((name, value))
            elif b & 0x10:                                 # Indexed Field Line With Post-Base Index
                idx, pos = dec_int(buf, pos, 4); out.append(self.t.absolute(base + idx))
            else:                                          # Literal With Post-Base Name Reference
                idx, pos = dec_int(buf, pos, 3); name = self.t.absolute(base + idx)[0]
                value, pos = qstr_dec(buf, pos, 7); out.append((name, value))
        ack = enc_int(stream_id, 7, 0x80) if ric else b""   # Section Acknowledgment only if dynamic refs
        return out, ack

def section_ack(stream_id):      return enc_int(stream_id, 7, 0x80)
def stream_cancel(stream_id):    return enc_int(stream_id, 6, 0x40)
def insert_count_inc(n):         return enc_int(n, 6, 0x00)

def encode_prefix(ric, base, max_capacity):
    if ric == 0:
        return b"\x00\x00"
    enc = ric % (2 * (max_capacity // 32)) + 1
    p = enc_int(enc, 8)
    return p + (enc_int(base - ric, 7, 0) if base &gt;= ric else enc_int(ric - base - 1, 7, 0x80))

class QEncoder:
    """Simple QPACK encoder. allow_blocking=False never references entries the
    decoder has not acknowledged (SETTINGS_QPACK_BLOCKED_STREAMS = 0)."""
    def __init__(self, capacity, allow_blocking=True, huff=True):
        self.cap, self.block, self.huff = capacity, allow_blocking, huff
        self.table, self.known = [], 0      # entries (abs order), Known Received Count
        self.enc_stream = enc_int(capacity, 5, 0x20)
    def _find(self, n, v):
        for i, e in enumerate(STATIC):
            if e == (n, v): return ("s", i)
        for a, e in enumerate(self.table):
            if e == (n, v): return ("d", a)
        return None
    def _static_name(self, n):
        for i, (sn, _) in enumerate(STATIC):
            if sn == n: return i
        return None
    def encode(self, fields):
        base = len(self.table); ric = 0; out = b""
        for n, v in fields:
            hit = self._find(n, v)
            if hit and hit[0] == "s":
                out += enc_int(hit[1], 6, 0xc0); continue
            if hit is None and sum(esize(*e) for e in self.table) + esize(n, v) &lt;= self.cap:
                sn = self._static_name(n)
                self.enc_stream += (enc_int(sn, 6, 0xc0) if sn is not None else qstr(n, 5, 0x40, self.huff)) + qstr(v, 7, 0, self.huff)
                self.table.append((n, v)); hit = ("d", len(self.table) - 1)
            if hit and (self.block or hit[1] &lt; self.known):
                a = hit[1]; ric = max(ric, a + 1)
                out += enc_int(base - 1 - a, 6, 0x80) if a &lt; base else enc_int(a - base, 4, 0x10)
            else:
                sn = self._static_name(n)
                out += (enc_int(sn, 4, 0x50) if sn is not None else qstr(n, 3, 0x20, self.huff)) + qstr(v, 7, 0, self.huff)
        return encode_prefix(ric, base, self.cap) + out, ric
