            s, r = e.encode(f); sizes.append(len(s)); rics.append(r); inserts.append(len(e.table))
        could_block = sum(1 for i, r in enumerate(rics) if r &gt; (inserts[i - ack_delay] if i &gt;= ack_delay else 0))
        print(f"blocking={'allowed' if blocking else 'forbidden':9s} ack after {ack_delay} req: request bytes {sizes[:5]}... total {sum(sizes)} B,"
              f" encoder stream {len(e.enc_stream)} B, sections that could block: {could_block}")


