                tcp_time_wait(sk, TCP_FIN_WAIT2, tmo);
That explains the odd ss line you will see in Lab 1: state fin-wait-2 with a timewait timer.
The ip-sysctl documentation says the same thing in prose: tcp_fin_timeout is “the length of time an orphaned (no longer referenced by any application) connection will remain in the FIN_WAIT_2 state before it is aborted at the local end.”

Production Implementations: Nginx, HAProxy, and Envoy






Note



Not run here. Production reverse proxies like Nginx, HAProxy, and Envoy require external daemon management, production configurations, and root privileges to bind privileged ports (such as 80 and 443), which are unavailable in this container.


Modern edge proxies leverage SO_REUSEPORT to scale across multi-core systems:

Nginx: Configured via the reuseport directive on the listen directive:
http {
    server {
        listen 80 reuseport;
        server_name example.com;
    }
}
Per the Nginx documentation, setting reuseport creates an individual listening socket for each worker process rather than inheriting a shared socket descriptor. The kernel then spreads handshakes across worker event loops instead of having workers compete for one shared listener. NGINX’s own 1.9.1 socket-sharding benchmark reported lower and more consistent latency with reuseport. Measure on your workload before assuming similar gains.
HAProxy: Historically relied on SO_REUSEPORT during reloads, so the new process could bind the same ports while the old one still held them. Because of the accept-queue drain problem above, modern HAProxy instead hands the existing listening sockets to the new process over its master/stats socket (expose-fd listeners, -x), which avoids the reset window.
Envoy: The listener’s enable_reuse_port setting gives each worker thread its own socket on the same port, so the kernel balances connections across workers.

Lab: four timestamps per datagram

The tool
udplat tx sends COUNT datagrams, recording t0 before each send(). It then drains the error queue to collect each t1, matched by the OPT_ID counter carried in ee_data. udplat rx receives, takes t2 from the SCM_TIMESTAMPING control message and t3 right after recvmsg() returns. It can block, spin with MSG_DONTWAIT, shrink its receive buffer, and burn a fixed amount of CPU per datagram to imitate application work.
// udplat.c - where do the microseconds go on one UDP datagram?
// tx: stamps t0 (user, before sendto) and t1 (kernel software TX timestamp,
//     taken as the driver hands the skb on), read back from MSG_ERRQUEUE.
// rx: stamps t2 (kernel software RX timestamp, taken on receive) and
//     t3 (user, right after recvmsg returns).
// All four are CLOCK_REALTIME on the same host, so they can be subtracted.
#define _GNU_SOURCE
#include &lt;arpa/inet.h&gt;
#include &lt;errno.h&gt;
#include &lt;linux/errqueue.h&gt;
#include &lt;linux/net_tstamp.h&gt;
#include &lt;poll.h&gt;
#include &lt;stdint.h&gt;
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;sys/socket.h&gt;
#include &lt;time.h&gt;
#include &lt;unistd.h&gt;

static int64_t now_ns(void) {
    struct timespec t; clock_gettime(CLOCK_REALTIME, &t);
    return (int64_t)t.tv_sec * 1000000000 + t.tv_nsec;
}
static int64_t ts_ns(struct timespec *t) { return (int64_t)t-&gt;tv_sec * 1000000000 + t-&gt;tv_nsec; }

static int64_t stamp_from(struct msghdr *m) {          // first SCM_TIMESTAMPING ts[0]
    for (struct cmsghdr *c = CMSG_FIRSTHDR(m); c; c = CMSG_NXTHDR(m, c))
        if (c-&gt;cmsg_level == SOL_SOCKET && c-&gt;cmsg_type == SCM_TIMESTAMPING)
            return ts_ns((struct timespec *)CMSG_DATA(c));
    return -1;
}

static int rx(int port, int spin, int rcvbuf, int work_us) {
    int s = socket(AF_INET, SOCK_DGRAM, 0);
    int f = SOF_TIMESTAMPING_RX_SOFTWARE | SOF_TIMESTAMPING_SOFTWARE;
    setsockopt(s, SOL_SOCKET, SO_TIMESTAMPING, &f, sizeof f);
    if (rcvbuf) setsockopt(s, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof rcvbuf);
    struct sockaddr_in a = {.sin_family = AF_INET, .sin_port = htons(port)};
    if (bind(s, (void *)&a, sizeof a)) { perror("bind"); return 1; }
    char buf[256], ctl[256];
    for (;;) {
        struct iovec io = {buf, sizeof buf};
        struct msghdr m = {.msg_iov = &io, .msg_iovlen = 1, .msg_control = ctl, .msg_controllen = sizeof ctl};
        ssize_t n;
        do n = recvmsg(s, &m, spin ? MSG_DONTWAIT : 0); while (n &lt; 0 && errno == EAGAIN);
        int64_t t3 = now_ns();
        uint32_t seq; memcpy(&seq, buf, 4);
        if (seq == 0xffffffff) break;                   // end marker
        printf("%u %lld %lld\n", seq, (long long)stamp_from(&m), (long long)t3);
        if (work_us) { int64_t until = now_ns() + work_us * 1000LL; while (now_ns() &lt; until) ; }
    }
    return 0;
}

static int tx(const char *dst, int port, int n, int gap_us) {
    int s = socket(AF_INET, SOCK_DGRAM, 0);
    int f = SOF_TIMESTAMPING_TX_SOFTWARE | SOF_TIMESTAMPING_SOFTWARE |
            SOF_TIMESTAMPING_OPT_ID | SOF_TIMESTAMPING_OPT_TSONLY;
    if (setsockopt(s, SOL_SOCKET, SO_TIMESTAMPING, &f, sizeof f)) { perror("SO_TIMESTAMPING"); return 1; }
    struct sockaddr_in a = {.sin_family = AF_INET, .sin_port = htons(port)};
    inet_pton(AF_INET, dst, &a.sin_addr);
    connect(s, (void *)&a, sizeof a);
    char buf[64] = {0}, ctl[256];
    int64_t *t0 = calloc(n, sizeof *t0), *t1 = calloc(n, sizeof *t1);
    for (uint32_t i = 0; i &lt; (uint32_t)n; i++) {
        memcpy(buf, &i, 4);
        t0[i] = now_ns();
        send(s, buf, sizeof buf, 0);
        if (gap_us) { int64_t until = t0[i] + gap_us * 1000LL; while (now_ns() &lt; until) ; }
    }
    // drain the error queue: one TX timestamp per datagram, ee_data = OPT_ID counter
    int got = 0;
    struct pollfd p = {s, POLLERR, 0};
    while (got &lt; n && poll(&p, 1, 500) &gt; 0) {
        struct msghdr m = {.msg_control = ctl, .msg_controllen = sizeof ctl};
        if (recvmsg(s, &m, MSG_ERRQUEUE) &lt; 0) break;
        int64_t t = stamp_from(&m); uint32_t id = 0;
        for (struct cmsghdr *c = CMSG_FIRSTHDR(&m); c; c = CMSG_NXTHDR(&m, c))
            if (c-&gt;cmsg_level == SOL_IP && c-&gt;cmsg_type == IP_RECVERR)
                id = ((struct sock_extended_err *)CMSG_DATA(c))-&gt;ee_data;
        if (id &lt; (uint32_t)n) { t1[id] = t; got++; }
    }
    uint32_t end = 0xffffffff; memcpy(buf, &end, 4);
    for (int k = 0; k &lt; 3; k++) send(s, buf, sizeof buf, 0);
    for (int i = 0; i &lt; n; i++) printf("%d %lld %lld\n", i, (long long)t0[i], (long long)t1[i]);
    return 0;
}

int main(int argc, char **argv) {
    if (argc &gt;= 3 && !strcmp(argv[1], "rx"))
        return rx(atoi(argv[2]), argc &gt; 3 && !strcmp(argv[3], "spin"),
                  argc &gt; 4 ? atoi(argv[4]) : 0, argc &gt; 5 ? atoi(argv[5]) : 0);
    if (argc &gt;= 6 && !strcmp(argv[1], "tx"))
        return tx(argv[2], atoi(argv[3]), atoi(argv[4]), atoi(argv[5]));
    fprintf(stderr, "usage: udplat rx PORT [block|spin] [RCVBUF] [WORK_US]\n"
                    "       udplat tx DST PORT COUNT GAP_US\n");
    return 2;
}
